INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) SELECT 'ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', concepto, enseñanza, ejemplo, NULL, NULL, NULL, orden FROM (VALUES ('Los Niveles de Dominio – De Básico a Gravedad Cero', 'El Hunter pasa por 4 niveles: Básico (explica el producto sin conectar beneficios), Medio (conecta beneficios y diagnostica), Alto (justifica el precio y maneja objeciones con autoridad), y Gravedad Cero (controla la conversación y cierra con autoridad, sin descuentos). El objetivo es llegar a Gravedad Cero: ser un asesor estratégico del restaurantero, no un vendedor más.', 'Básico: "INVU tiene facturación electrónica nativa."  
Medio: "INVU incluye FE nativa, así que te ahorras S/120/mes en Nubefact."  
Alto: "Cuando sumas el PSE, soporte y sistemas separados, la competencia te cuesta S/450/mes. INVU es S/350/mes todo incluido. Y el onboarding consultivo te da visibilidad de márgenes que nunca tuviste."  
Gravedad Cero: El cliente dice: "¿Qué necesito firmar?" El Hunter ya no vende; el cliente compra porque confía en él.


# PÍLDORAS DE CONOCIMIENTO - PROGRAMA DE REFERIDOS INVU POS PERÚ', 31),
('El Programa de Referidos – La Puerta de Entrada sin Esfuerzo', 'El Programa de Referidos INVU está diseñado para que cualquier persona con contactos en la industria gastronómica pueda monetizar su red sin necesidad de ser vendedor. El referidor no vende, no hace demos, no cotiza y no implementa. Su única función es abrir la puerta: identificar un negocio que califique, contactar al tomador de decisión, presentar a INVU como el socio recomendado, y asegurar una reunión. El equipo de INVU hace el resto. Es el programa de referidos más simple y accesible del mercado peruano.', 'Un cliente satisfecho de INVU, dueño de un restaurante, conoce a otro restaurador que tiene problemas con su facturación electrónica. El cliente le dice: "Oye, INVU me cambió la vida. Te recomiendo que los conozcas. ¿Quieres que los contacte para que te hagan una demo sin compromiso?" El restaurador acepta. El cliente envía un correo a INVU con los datos de contacto. El equipo de INVU agenda la reunión, cierra la venta, y el cliente referidor cobra S/1,000 sin haber hecho nada más que abrir la puerta.', 32),
('Comisiones Fijas – Transparencia Total', 'El referidor cobra una comisión fija según el tamaño del negocio: S/500 para negocio pequeño (1-2 sedes), S/1,000 para negocio en crecimiento (3-5 sedes), S/1,500 para cuenta consolidada (más de 5 sedes). No hay porcentajes variables, no hay condiciones de permanencia, no hay pagos fraccionados. El referidor sabe exactamente cuánto va a ganar desde el momento en que identifica el negocio. Esta transparencia es un diferenciador clave frente a otros programas de referidos.', 'Un proveedor de insumos conoce a una cadena de 10 restaurantes. Sabe que si refiere ese negocio a INVU, cobrará S/1,500 cuando el cliente firme y pague su primera factura. No tiene que calcular porcentajes ni preocuparse por si el cliente se mantiene 6 o 12 meses. El cálculo es simple: S/1,500. Esta claridad lo motiva a hacer la referencia.', 33),
('Protección de Oportunidad – 90 Días de Exclusividad', 'El referidor que registra primero un negocio queda como propietario de esa oportunidad durante 90 días. Si el negocio avanza y cierra dentro de ese plazo, la comisión es para el referidor que lo registró. Esto elimina la competencia desleal y protege el esfuerzo del referidor. Es la garantía de que su trabajo no será aprovechado por otro.', 'Un referidor identifica un restaurante de 3 sedes, contacta al dueño, y registra la oportunidad en INVU mediante correo a lizeth@invupos.com. Dos semanas después, otro referidor intenta registrar el mismo negocio. INVU verifica que el primero ya lo tiene registrado y protege la oportunidad del referidor original. Este último tiene la tranquilidad de que su comisión está asegurada si el negocio cierra dentro de los 90 días.', 34),
('El Proceso de 3 Pasos – Simple y Sin Complicaciones', 'El programa de referidos tiene un proceso simple de tres pasos: Preséntanos (contacta al decisor y presenta a INVU), Facilita los datos (envía contacto e información clave a INVU), Asegura la cita (deja la reunión agendada). De ahí en adelante, INVU toma el control. El referidor no tiene que hacer demos, ni cotizaciones, ni seguimiento comercial. El proceso es tan simple que cualquier persona, sin importar su experiencia en ventas, puede participar.', 'Un contador con clientes restauranteros quiere referirlos a INVU. No sabe cómo hacer una demo ni cómo manejar objeciones técnicas. Pero el proceso de 3 pasos es simple: 1) Contacta a su cliente dueño de un restaurante y le dice que INVU es el sistema que recomienda. 2) Envía un correo a lizeth@invupos.com con los datos del cliente. 3) Agenda una reunión entre el cliente y el equipo de INVU. El contador no necesita saber nada más; INVU hace el resto.', 35),
('El Perfil del Cliente Ideal para Referir', 'El referidor debe enfocar sus esfuerzos en negocios que califiquen: restaurantes, bares, cafeterías, franquicias, cadenas de comida, o comercios gastronómicos que facturen al menos S/30,000 mensuales. Si el negocio no cumple con este perfil, probablemente no sea un buen cliente para INVU y el referidor perderá tiempo. Identificar el perfil correcto es el primer paso para maximizar la efectividad del referidor.', 'Un referidor conoce a un amigo que tiene una pequeña cafetería que factura S/10,000 mensuales. Sabe que este negocio no califica para INVU, así que no pierde tiempo refiriéndolo. En cambio, enfoca sus esfuerzos en otro contacto: un dueño de una cadena de 5 restaurantes que factura S/150,000 mensuales. Este sí califica y el referidor puede ganar S/1,000 por la referencia.', 36),
('Las 7 Preguntas del Referidor – Calificar Antes de Referir', 'El referidor debe hacer 7 preguntas de diagnóstico antes de referir un negocio: sector gastronómico o comercial, número de sedes, facturación mensual, sistema actual y dolor, tomador de decisión, problemas específicos (facturación, inventario, centralización, retención de clientes), y planes de crecimiento. Estas preguntas aseguran que el negocio califica y que INVU tiene una oportunidad real de cerrar la venta.', 'Un referidor contacta a un conocido dueño de un restaurante. En lugar de referirlo inmediatamente, hace las 7 preguntas: "¿Cuántas sedes tienes? ¿Qué sistema usas hoy? ¿Cómo manejas la facturación electrónica? ¿Tienes recetas costeadas? ¿Quién toma las decisiones? ¿Tienes planes de abrir más locales?" Al obtener las respuestas, el referidor confirma que el negocio califica y que el dolor principal es la falta de centralización. Ahora puede presentar a INVU de manera más efectiva, enfocándose en ese dolor.', 37),
('El Mensaje que Abre Puertas – Presentación Sin Presión', 'El referidor debe presentar a INVU de manera atractiva pero sin presión, conectando con el dolor del negocio. Un buen mensaje es: "Conozco a INVU POS, es el sistema que usan más de 5,000 restaurantes en Latam. Son especialistas en restaurantes, incluyen facturación electrónica nativa y te dejan el negocio operando desde el día uno. Creo que pueden ayudarte con [el dolor específico]. Te recomiendo que los conozcas." Esta presentación es breve, clara y enfocada en el beneficio.', 'Un referidor le dice a un dueño de restaurante: "Oye, sé que has tenido problemas con el inventario y la facturación electrónica en tus 3 locales. Te quiero recomendar INVU POS, el sistema que usamos en mi restaurante. Nos cambió la vida: incluimos facturación electrónica nativa sin pagar extra a Nubefact, centralizamos el inventario de los 2 locales, y vemos reportes en tiempo real desde el celular. ¿Quieres que los contacte para que te hagan una demo sin compromiso?" El dueño, que confía en el referidor, acepta.', 38),
('El Cierre del Referidor – Asegurar la Reunión', 'El cierre del referidor no es cerrar una venta; es asegurar una reunión. El referidor debe preguntar: "¿Te parece si los contacto para que te hagan una demo enfocada en tu negocio? No hay compromiso, solo conoces la solución. ¿Qué día te acomoda?" Cuando el referidor asegura la reunión, su trabajo está hecho. Luego registra la oportunidad en INVU y espera su comisión.', 'Un referidor ha presentado INVU a un colega restaurador. El colega muestra interés. El referidor cierra: "¿Qué te parece si les paso tu contacto para que te llamen y agenden una reunión? Ellos se encargan de todo. ¿Te parece bien? ¿Qué día te acomoda?" El colega dice: "El jueves a las 10am." El referidor envía el correo de registro a INVU y su comisión está protegida.', 39),
('El Registro Correcto – Protege tu Comisión', 'El referidor debe registrar la oportunidad formalmente mediante correo a lizeth@invupos.com con copia a jorge@invupos.com, incluyendo: nombre del negocio, nombre y cargo del tomador de decisión, teléfono y correo de contacto, número de sedes, facturación aproximada, y sistema actual. Sin este registro, la comisión del referidor no está protegida. Lo que no está registrado, no existe.', 'Un referidor asegura una reunión con un dueño de restaurante, pero no envía el correo de registro. Dos semanas después, otro referidor registra el mismo negocio. El primero pierde la comisión porque no protegió su oportunidad. El segundo referidor, que sí registró, cobra S/1,000 cuando el negocio cierra. El referidor que no registró aprende la lección.', 40),
('El Valor del Esfuerzo vs. la Comisión', 'El referidor invierte entre 1 y 3 horas para identificar, contactar, presentar y registrar un negocio. Por ese esfuerzo, puede ganar S/500, S/1,000 o S/1,500. La tasa de retorno es de S/167 a S/500 por hora, muy superior al ingreso promedio en Perú. Si el referidor mantiene una red de contactos activa y refiere negocios regularmente, puede generar un ingreso complementario significativo con bajo esfuerzo.', 'Un contador refiere 1 negocio pequeño al mes (S/500). Son 3 horas de trabajo al mes. Ingreso anual: S/6,000. Si refiere 1 negocio en crecimiento al mes (S/1,000), son S/12,000 anuales. Si refiere 1 cuenta consolidada al mes (S/1,500), son S/18,000 anuales. Todo con 3 horas de trabajo al mes. El esfuerzo es mínimo; el retorno es alto.', 41),
('El Riesgo Cero para el Referidor', 'El referidor no asume ningún riesgo financiero. No invierte dinero, no firma contratos, no garantiza el pago del cliente. Su único riesgo es que el negocio referido no cierre dentro de los 90 días, lo que significaría que su esfuerzo de 1-3 horas no rinde fruto. Dado que INVU tiene un alto índice de cierre en negocios calificados, este riesgo es muy bajo. El referidor solo gana; nunca pierde.', 'Un referidor identifica un negocio potencial y lo registra. El negocio no cierra dentro de los 90 días por razones ajenas al referidor (el dueño decidió posponer la inversión). El referidor no pierde dinero; solo perdió 3 horas de su tiempo. Pero tiene otros contactos en su red y sigue refiriendo. Eventualmente, uno de sus referidos cierra y cobra su comisión. El riesgo es mínimo.', 42),
('La Comparación – Por qué INVU es Superior a Otros Programas', 'Otros programas de referidos tienen comisiones variables basadas en porcentaje (5-15%), condiciones de permanencia del cliente (6-12 meses), exigencia de participación en el proceso de venta, y sin protección de oportunidad. INVU ofrece comisiones fijas (S/500, S/1,000, S/1,500), sin condiciones de permanencia, sin exigencia de participación en ventas, y con protección de oportunidad por 90 días. El programa de INVU es más simple, más transparente y más rentable para el referidor.', 'Un referidor compara dos programas. En el programa X, la comisión es del 10% de la venta, pero el cliente debe permanecer 12 meses y el referidor debe ayudar en las demos. En INVU, la comisión es fija (S/1,000 para un negocio de 3 sedes), sin condiciones de permanencia, y el referidor solo abre la puerta. El referidor elige INVU porque es más simple y menos riesgoso.', 43),
('El Potencial de Ingresos Ilimitado', 'El referidor puede referir múltiples negocios y acumular comisiones sin límite. No hay tope de ingresos ni restricción de cantidad de referidos. Cuantos más negocios conecte, más comisiones acumula. Puede convertirlo en un ingreso recurrente si tiene una red de contactos activa en la industria gastronómica. El potencial de ingresos es ilimitado.', 'Un proveedor de insumos tiene una red de 50 clientes restauranteros. Refiere a 10 de ellos a INVU en un año. Si la mayoría son negocios de 3-5 sedes, gana S/1,000 por cada uno = S/10,000 anuales. Si algunos son cuentas consolidadas, gana S/1,500 por cada uno. El ingreso es significativo y el esfuerzo es compartido. El proveedor no tiene que vender; solo abrir la puerta.
```', 44)) AS t(concepto, enseñanza, ejemplo, orden);